class Solution {
    public String findDifferentBinaryString(String[] nums){
        char[] answer=new char[nums.length];
        for(int i=0;i<nums.length;i++)answer[i]=nums[i].charAt(i)=='0'?'1':'0';
        return new String(answer);
    }
}

code.cpp:
class Solution {
    public: string findDifferentBinaryString(vector<string>& nums){
        string answer(nums.size(),'0');
        for(int i=0;i<(int)nums.size();++i)answer[i]=nums[i][i]=='0'?'1':'0';
        return answer;
    }
};
